SELECT COUNT(*) AS rent_listings_count
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS yoga_mat_count
FROM nlq.listings
WHERE title ILIKE '%yoga mat%' OR description ILIKE '%yoga mat%';

select max(agreed_price) as max_sale_price
from nlq.my_deals
where my_role = 'seller' and status = 'completed' and deal_type = 'sale';

SELECT COUNT(*) AS deactivated_accounts
FROM nlq.students
WHERE account_status = 'deactivated';

select count(*) as conversations_no_reply
from nlq.conversations
where first_seller_reply_at is null;

SELECT round(avg((resolved_at AT TIME ZONE 'America/New_York')::date - (filed_at AT TIME ZONE 'America/New_York')::date)::numeric, 2) AS avg_days_to_resolve
FROM nlq.reports
WHERE status = 'resolved';

select count(*) as pending_requests
from nlq.deals
where status = 'requested';
